alter function public.create_payment_order(text,uuid,text,integer) set schema pa_private;
create or replace function public.create_payment_order(p_plan text,p_external_uuid uuid,p_affiliate_code text default null,p_expected_price_cents integer default null) returns public.payment_orders language sql security invoker set search_path='' as $$ select pa_private.create_payment_order(p_plan,p_external_uuid,p_affiliate_code,p_expected_price_cents); $$;
revoke all on function public.create_payment_order(text,uuid,text,integer) from public,anon;
grant execute on function public.create_payment_order(text,uuid,text,integer) to authenticated;
